# recompute: find frames & interiors automatically
def find_frames(g):
    from collections import deque
    seen=set(); frames={}
    H,W=len(g),len(g[0])
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v and (r,c) not in seen:
                q=deque([(r,c)]); comp={(r,c)}; seen.add((r,c))
                while q:
                    a,b=q.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]==v:
                            seen.add((x,y)); comp.add((x,y)); q.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                frames[v]=(min(rs),max(rs),min(cs),max(cs))
    return frames
